<?php session_start(); require 'config/database.php'; require 'lib_security.php'; require 'lib_academic.php'; if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='admin'){header('Location: login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete'])){verifyCsrf();$pdo->prepare('DELETE FROM subjects WHERE id=?')->execute([(int)$_POST['delete']]);header('Location: subjects.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ verifyCsrf();$id=(int)($_POST['id']??0);$v=[(int)$_POST['program_id'],trim($_POST['code']??''),trim($_POST['name']),trim($_POST['semester']??'')?:null,(float)($_POST['credit_hours']??3)];if($id)$pdo->prepare('UPDATE subjects SET program_id=?,code=?,name=?,semester=?,credit_hours=? WHERE id=?')->execute([...$v,$id]);else$pdo->prepare('INSERT INTO subjects(program_id,code,name,semester,credit_hours) VALUES(?,?,?,?,?)')->execute($v);header('Location: subjects.php');exit;}
$programs=$pdo->query('SELECT * FROM programs WHERE active=1 ORDER BY FIELD(level,"HSSC","BS","ADP"),name')->fetchAll();$rows=$pdo->query('SELECT s.*,p.level,p.name program_name FROM subjects s JOIN programs p ON p.id=s.program_id ORDER BY p.name,s.semester,s.name')->fetchAll();$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM subjects WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$pageTitle='Subjects';require'includes/header.php';?>
<div class="container py-4"><div class="d-flex justify-content-between"><h2>Subjects</h2><a href="admin.php" class="btn btn-outline-secondary">Dashboard</a></div><div class="card shadow-sm my-3"><div class="card-body"><form method="post" class="row g-2"><?php echo csrfField(); ?><input type="hidden" name="id" value="<?=htmlspecialchars($edit['id']??'')?>"><div class="col-md-3"><select name="program_id" class="form-select" required><option value="">Select Program</option><?php foreach($programs as $p):?><option value="<?=$p['id']?>" <?=($edit['program_id']??0)==$p['id']?'selected':''?>><?=$p['level']?> — <?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input name="code" class="form-control" placeholder="Code" value="<?=htmlspecialchars($edit['code']??'')?>"></div><div class="col-md-3"><input name="name" class="form-control" placeholder="Subject name" required value="<?=htmlspecialchars($edit['name']??'')?>"></div><div class="col-md-2"><select name="semester" id="subjectTerm" class="form-select"><option value="">All / General</option></select></div><div class="col-md-1"><input name="credit_hours" type="number" step="0.5" class="form-control" value="<?=htmlspecialchars($edit['credit_hours']??3)?>"></div><div class="col-md-1"><button class="btn btn-primary">Save</button></div></form><script>const terms={HSSC:['Part-I','Part-II'],BS:['1st Semester','2nd Semester','3rd Semester','4th Semester','5th Semester','6th Semester','7th Semester','8th Semester'],ADP:['1st Year','2nd Year','1st Semester','2nd Semester','3rd Semester','4th Semester']};const p=document.querySelector('[name="program_id"]'),t=document.getElementById('subjectTerm'),old='<?=htmlspecialchars($edit["semester"]??"")?>';function fill(){const level=p.options[p.selectedIndex]?.text.split(' — ')[0];t.innerHTML='<option value="">All / General</option>'+(terms[level]||[]).map(x=>'<option '+(x===old?'selected':'')+'>'+x+'</option>').join('');}p.addEventListener('change',fill);fill();</script></div></div><div class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Program</th><th>Code</th><th>Subject</th><th>Semester</th><th>CH</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['level']?> — <?=htmlspecialchars($r['program_name'])?></td><td><?=htmlspecialchars($r['code']??'')?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['semester']??'—')?></td><td><?=$r['credit_hours']?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">Edit</a> <form method="post" class="d-inline" onsubmit="return confirm('Delete subject?')"><?php echo csrfField(); ?><button name="delete" value="<?=$r['id']?>" class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require'includes/footer.php';?>
